SELECT ?s ?name ?class ?tsid WHERE {
  ?s ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
  ?s rdfs:label ?name .
  FILTER(?name IN ("AHU01","CondPump02","HWPump01"))
}

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(str(?s) contains "AHU01" || str(?s) contains "Pump")
} LIMIT 30

